import { useEffect, useMemo, useState } from 'react'
import {
  FORTUNES,
  type Fortune,
  pickPercent,
  predictFromText,
  shuffledFortunes,
} from './data/fortunes'
import './App.css'

type Screen = 'home' | 'shuffle' | 'select' | 'reveal' | 'result' | 'ai'

const SHUFFLE_LINES = [
  '?밸━??湲곗슫??遺덈윭?ㅻ뒗 以?..',
  '?ㅻ뒛???먮쫫???쎈뒗 以?..',
  '?밸━ ?濡쒕? ?욌뒗 以?..',
]

const COUNTER_KEY = 'ainii-taro-draws'
const BASE_COUNT = 1284

function readCounter(): number {
  try {
    const n = Number(localStorage.getItem(COUNTER_KEY) ?? 0)
    return Number.isFinite(n) ? n : 0
  } catch {
    return 0
  }
}

function bumpCounter(): number {
  const next = readCounter() + 1
  try {
    localStorage.setItem(COUNTER_KEY, String(next))
  } catch {
    /* ignore */
  }
  return next
}

function AeniSlot({ note }: { note?: string }) {
  return (
    <div className="aeni-slot" aria-hidden="true">
      <div className="aeni-slot__ring" />
      <p className="aeni-slot__label">{note ?? '?좎씠???대?吏 ?덉젙'}</p>
    </div>
  )
}

export default function App() {
  const [screen, setScreen] = useState<Screen>('home')
  const [localDraws, setLocalDraws] = useState(0)
  const [shuffleLine, setShuffleLine] = useState(SHUFFLE_LINES[0])
  const [deck, setDeck] = useState<Fortune[]>(FORTUNES)
  const [picked, setPicked] = useState<Fortune | null>(null)
  const [percent, setPercent] = useState(0)
  const [aiText, setAiText] = useState('')
  const [aiLine, setAiLine] = useState('')

  const totalShown = useMemo(() => BASE_COUNT + localDraws, [localDraws])

  useEffect(() => {
    setLocalDraws(readCounter())
  }, [])

  useEffect(() => {
    if (screen !== 'shuffle') return
    let i = 0
    setShuffleLine(SHUFFLE_LINES[0])
    const tick = window.setInterval(() => {
      i = (i + 1) % SHUFFLE_LINES.length
      setShuffleLine(SHUFFLE_LINES[i])
    }, 900)
    const done = window.setTimeout(() => {
      setDeck(shuffledFortunes())
      setScreen('select')
    }, 2800)
    return () => {
      window.clearInterval(tick)
      window.clearTimeout(done)
    }
  }, [screen])

  useEffect(() => {
    if (screen !== 'reveal' || !picked) return
    const t = window.setTimeout(() => setScreen('result'), 1600)
    return () => window.clearTimeout(t)
  }, [screen, picked])

  function startDraw() {
    setPicked(null)
    setPercent(0)
    setAiLine('')
    setScreen('shuffle')
  }

  function chooseCard(card: Fortune) {
    const p = pickPercent(card.percentRange)
    setPicked(card)
    setPercent(p)
    setLocalDraws(bumpCounter())
    setScreen('reveal')
  }

  function resetHome() {
    setPicked(null)
    setPercent(0)
    setAiText('')
    setAiLine('')
    setScreen('home')
  }

  function runAiPredict() {
    if (!aiText.trim()) return
    const r = predictFromText(aiText)
    setPicked(r.fortune)
    setPercent(r.percent)
    setAiLine(r.line)
    setLocalDraws(bumpCounter())
    setScreen('result')
  }

  return (
    <div className="app">
      <div className="stage">
        {screen === 'home' && (
          <section className="panel home" aria-label="硫붿씤">
            <p className="eyebrow">?좎씠?덉쓽 履쎌쭛寃?AI ?濡??댁꽭</p>
            <h1 className="title">
              ?ㅻ뒛 ?섏뿉寃??ㅼ뼱??n              <br />
              ?밸━??湲곗슫??
            </h1>
            <AeniSlot />
            <p className="lead">
              媛??AI ?좎씠???먯닠媛媛 ?ㅻ뒛???밸━ ?濡쒕? 以鍮꾪뻽?듬땲??
              <br />
              ?좎젣怨?쨌 ??쟾 쨌 泥좊꼍 ?섎퉬 쨌 ?묒썝 ?닿린 以?n              <br />
              ?ㅻ뒛 媛??媛뺥븯寃??ㅼ뼱???밸━?댁쓣 ?먮룆?⑸땲??
            </p>
            <p className="counter">
              吏湲덇퉴吏 <strong>{totalShown.toLocaleString('ko-KR')}</strong>紐낆씠
              ?밸━??湲곗슫???뺤씤?덉뼱??n            </p>
            <button type="button" className="btn btn-cloud" onClick={startDraw}>
              ?밸━ ?濡?戮묎린
            </button>
            <button
              type="button"
              className="btn btn-ghost"
              onClick={() => setScreen('ai')}
            >
              臾멸뎄濡??댁꽭 蹂닿린
            </button>
          </section>
        )}

        {screen === 'shuffle' && (
          <section className="panel shuffle" aria-live="polite">
            <p className="eyebrow">STEP 1</p>
            <h2 className="title sm">
              寃쎄린 ?쒖옉 ??
              <br />
              ?뱀떊?먭쾶 李얠븘???밸━??湲곗슫??
            </h2>
            <AeniSlot note="移대뱶 ?욌뒗 以?.." />
            <div className="shuffle-cards" aria-hidden="true">
              {[0, 1, 2, 3].map((i) => (
                <div key={i} className={`card-back float f${i}`} />
              ))}
            </div>
            <p className="status">{shuffleLine}</p>
            <p className="hint">移대뱶瑜??욊퀬 ?덉쑝???좎떆 湲곕떎??二쇱꽭??</p>
          </section>
        )}

        {screen === 'select' && (
          <section className="panel select">
            <p className="eyebrow">STEP 2??</p>
            <h2 className="title sm">媛???뚮━??移대뱶 ???μ쓣 ?좏깮?섏꽭??/h2>
            <p className="status ready">???μ쓽 移대뱶媛 以鍮꾨릺?덉뒿?덈떎</p>
            <div className="card-fan" role="list">
              {deck.map((card, idx) => (
                <button
                  key={card.id}
                  type="button"
                  className={`card-back pick p${idx}`}
                  role="listitem"
                  aria-label={`?밸━ ?濡?移대뱶 ${idx + 1}`}
                  onClick={() => chooseCard(card)}
                />
              ))}
            </div>
            <p className="hint">?좎씠?덇? 移대뱶瑜??욎뼱 ?쒖떆?덉뼱??/p>
          </section>
        )}

        {screen === 'reveal' && picked && (
          <section className="panel reveal" aria-live="polite">
            <div className="burst" aria-hidden="true" />
            <div
              className="card-face rising"
              style={{ borderColor: picked.accent }}
            >
              <span className="card-face__tag">VICTORY TAROT</span>
              <strong>{picked.title}</strong>
              <span>{picked.subtitle}</span>
            </div>
            <p className="status">
              ?좏깮??移대뱶???밸━??湲곗슫??紐⑥씠怨??덉뒿?덈떎.
              <br />
              ?ㅻ뒛???밸━?댁쓣 怨듦컻?⑸땲??
            </p>
          </section>
        )}

        {screen === 'result' && picked && (
          <section className="panel result">
            <div className="scroll">
              <p className="eyebrow">?ㅻ뒛???밸━??/p>
              <div
                className="card-face mini"
                style={{ borderColor: picked.accent }}
              >
                <strong>{picked.title}</strong>
              </div>
              <p className="percent" style={{ color: picked.accent }}>
                ?댁닔 <strong>{percent}%</strong>
              </p>
              <p className="blurb">{aiLine || picked.blurb}</p>
            </div>
            <button type="button" className="btn btn-cloud" onClick={resetHome}>
              ?뚯븘媛湲?n            </button>
          </section>
        )}

        {screen === 'ai' && (
          <section className="panel ai">
            <p className="eyebrow">異붽? ?댁꽭</p>
            <h2 className="title sm">
              臾멸뎄瑜??ｌ쑝硫?n              <br />
              ?ㅻ뒛??湲곗슫???쎌뼱?쒕젮??n            </h2>
            <AeniSlot note="?ㅼ썙???먯닠" />
            <label className="field">
              <span className="sr-only">?댁꽭 臾멸뎄</span>
              <textarea
                value={aiText}
                onChange={(e) => setAiText(e.target.value)}
                placeholder="?? ?몄쿇 ?좎젣怨? ?ы빆????쟾, ?ㅻ뒛 ?묒썝 ?닿린..."
                rows={3}
                maxLength={120}
              />
            </label>
            <button
              type="button"
              className="btn btn-cloud"
              onClick={runAiPredict}
              disabled={!aiText.trim()}
            >
              湲곗슫 ?먮룆?섍린
            </button>
            <button type="button" className="btn btn-ghost" onClick={resetHome}>
              ?뚯븘媛湲?n            </button>
          </section>
        )}
      </div>
    </div>
  )
}

.app {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 12px;
}

.stage {
  width: min(100%, 420px);
  min-height: min(92dvh, 860px);
  border-radius: 28px;
  overflow: hidden;
  position: relative;
  box-shadow: var(--shadow);
  background:
    linear-gradient(180deg, rgba(90, 30, 120, 0.35), transparent 30%),
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 48px,
      rgba(255, 255, 255, 0.015) 48px,
      rgba(255, 255, 255, 0.015) 49px
    ),
    radial-gradient(1.5px 1.5px at 12% 18%, #fff8, transparent),
    radial-gradient(1px 1px at 78% 22%, #fff6, transparent),
    radial-gradient(1.5px 1.5px at 40% 70%, #fff5, transparent),
    radial-gradient(1px 1px at 88% 64%, #fff4, transparent),
    linear-gradient(180deg, #4a1f78 0%, #2a1048 42%, #140820 100%);
  border: 1px solid rgba(255, 220, 255, 0.12);
}

.stage::before,
.stage::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 18%;
  pointer-events: none;
  background: linear-gradient(90deg, rgba(60, 10, 90, 0.75), transparent);
  z-index: 0;
}

.stage::after {
  right: 0;
  left: auto;
  background: linear-gradient(-90deg, rgba(60, 10, 90, 0.75), transparent);
}

.panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 14px;
  padding: 28px 20px 24px;
  min-height: min(92dvh, 860px);
}

.eyebrow {
  margin: 0;
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  color: var(--gold);
  font-weight: 700;
}

.title {
  margin: 0;
  font-family: 'Black Han Sans', 'Pretendard', sans-serif;
  font-size: clamp(1.55rem, 6.2vw, 1.95rem);
  font-weight: 400;
  line-height: 1.25;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.25);
}

.title.sm {
  font-size: clamp(1.25rem, 5vw, 1.55rem);
}

.lead,
.hint,
.status,
.blurb,
.counter {
  margin: 0;
  color: var(--muted);
  font-size: 0.92rem;
}

.counter strong {
  color: var(--gold);
}

.status {
  color: #ffe8ff;
  font-weight: 600;
}

.status.ready {
  color: var(--gold);
}

.aeni-slot {
  width: min(72%, 240px);
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  position: relative;
  background:
    radial-gradient(circle at 50% 40%, rgba(255, 180, 220, 0.2), transparent 55%),
    rgba(255, 255, 255, 0.04);
  border: 2px dashed rgba(255, 200, 230, 0.35);
  margin: 4px 0 8px;
}

.aeni-slot__ring {
  position: absolute;
  inset: 10%;
  border-radius: 50%;
  border: 1px solid rgba(255, 200, 230, 0.2);
  animation: pulse 2.4s ease-in-out infinite;
}

.aeni-slot__label {
  margin: 0;
  font-size: 0.85rem;
  color: rgba(255, 230, 245, 0.7);
}

.btn {
  appearance: none;
  border: none;
  cursor: pointer;
  transition: transform 0.15s ease, filter 0.15s ease, opacity 0.15s;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn:not(:disabled):active {
  transform: scale(0.97);
}

.btn-cloud {
  min-width: 220px;
  padding: 16px 28px 18px;
  border-radius: 999px;
  font-weight: 800;
  font-size: 1.05rem;
  color: #4a1a6a;
  background:
    radial-gradient(circle at 18% 30%, #fff 0 8px, transparent 9px),
    radial-gradient(circle at 82% 35%, #ffe08a 0 10px, transparent 11px),
    linear-gradient(180deg, #f3e7ff 0%, #d9b8ff 100%);
  box-shadow:
    0 8px 0 #8b5cb8,
    0 12px 24px rgba(0, 0, 0, 0.25);
}

.btn-cloud:not(:disabled):hover {
  filter: brightness(1.05);
}

.btn-ghost {
  background: transparent;
  color: var(--muted);
  text-decoration: underline;
  text-underline-offset: 4px;
  padding: 8px 12px;
}

.shuffle-cards {
  display: flex;
  gap: 8px;
  height: 120px;
  align-items: center;
  justify-content: center;
}

.card-back {
  width: 72px;
  height: 110px;
  border-radius: 10px;
  border: 2px solid #f0c75e;
  background:
    radial-gradient(circle at 50% 35%, #ffe08a 0 10%, transparent 11%),
    repeating-linear-gradient(
      45deg,
      #c48a1a 0 2px,
      #e8b43a 2px 6px
    ),
    linear-gradient(160deg, #f6d56a, #b8860b);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.35);
  position: relative;
}

.card-back::after {
  content: '?';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 1.4rem;
  color: rgba(90, 40, 0, 0.55);
}

.card-back.float {
  animation: bob 1.1s ease-in-out infinite;
}

.card-back.float.f1 {
  animation-delay: 0.15s;
}
.card-back.float.f2 {
  animation-delay: 0.3s;
}
.card-back.float.f3 {
  animation-delay: 0.45s;
}

.card-fan {
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 0;
  width: 100%;
  min-height: 200px;
  padding: 24px 8px 8px;
}

.card-back.pick {
  width: 78px;
  height: 118px;
  margin: 0 -8px;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card-back.pick.p0 {
  transform: rotate(-14deg) translateY(18px);
}
.card-back.pick.p1 {
  transform: rotate(-5deg) translateY(4px);
}
.card-back.pick.p2 {
  transform: rotate(5deg) translateY(4px);
}
.card-back.pick.p3 {
  transform: rotate(14deg) translateY(18px);
}

.card-back.pick:hover,
.card-back.pick:focus-visible {
  transform: translateY(-12px) scale(1.06);
  z-index: 2;
  outline: 2px solid #fff;
  outline-offset: 3px;
}

.reveal {
  justify-content: center;
}

.burst {
  position: absolute;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: conic-gradient(
    from 0deg,
    transparent,
    rgba(255, 210, 80, 0.55),
    transparent 12%,
    transparent 20%,
    rgba(255, 210, 80, 0.45),
    transparent 32%
  );
  animation: spin 8s linear infinite, glow 1.6s ease-in-out infinite;
  z-index: 0;
}

.card-face {
  position: relative;
  z-index: 1;
  width: 180px;
  min-height: 260px;
  border-radius: 14px;
  border: 3px solid var(--gold);
  background: linear-gradient(180deg, #fff8e8, #ffe6b0);
  color: #3b1d0a;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px 14px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.4);
}

.card-face.rising {
  animation: rise 0.7s ease-out;
}

.card-face__tag {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  opacity: 0.7;
}

.card-face strong {
  font-family: 'Black Han Sans', sans-serif;
  font-size: 1.45rem;
  font-weight: 400;
}

.card-face.mini {
  width: 140px;
  min-height: 120px;
  margin: 0 auto 8px;
}

.scroll {
  width: 100%;
  max-width: 340px;
  padding: 28px 22px 32px;
  border-radius: 8px 8px 18px 18px;
  background:
    linear-gradient(180deg, #f6e2b8 0%, #e8c98a 100%);
  color: #3a2410;
  box-shadow: inset 0 0 0 2px rgba(120, 80, 20, 0.2), var(--shadow);
}

.scroll .eyebrow {
  color: #8a5a10;
}

.scroll .blurb {
  color: #4a3018;
  font-size: 0.98rem;
  text-align: left;
  line-height: 1.65;
}

.percent {
  margin: 4px 0 12px;
  font-size: 1.35rem;
}

.percent strong {
  font-size: 1.8rem;
  font-family: 'Black Han Sans', sans-serif;
}

.field {
  width: 100%;
}

.field textarea {
  width: 100%;
  resize: vertical;
  border-radius: 16px;
  border: 2px solid rgba(255, 220, 255, 0.25);
  background: rgba(20, 8, 32, 0.55);
  color: var(--ink);
  padding: 14px;
  outline: none;
}

.field textarea:focus {
  border-color: var(--gold);
}

.panel.ai .btn-cloud {
  margin-top: 4px;
}

@keyframes bob {
  0%,
  100% {
    transform: translateY(0) rotate(-4deg);
  }
  50% {
    transform: translateY(-10px) rotate(4deg);
  }
}

@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.7;
  }
  50% {
    transform: scale(1.04);
    opacity: 1;
  }
}

@keyframes rise {
  from {
    transform: scale(0.6) rotate(-8deg);
    opacity: 0;
  }
  to {
    transform: scale(1) rotate(0);
    opacity: 1;
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes glow {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.25);
  }
}

@media (min-width: 768px) {
  .stage {
    width: min(100%, 460px);
  }
}

